from collections import defaultdict

def valid_tree(n, edges):
    if len(edges) != n - 1:
        return False
    g = defaultdict(list)
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    seen = set()
    def dfs(u, parent):
        seen.add(u)
        for v in g[u]:
            if v == parent:
                continue
            if v in seen:
                return False
            if not dfs(v, u):
                return False
        return True
    return dfs(0, -1) and len(seen) == n
